_CORE_SRC = '# Action format: [(from_node, to_node, count), ...]\n# Payout: capacity_i = drones_i * 5; served_i = capacity_i * demand / max(total_capacity, demand).\n# Cost: 2.0 per drone not on its own base after moves, per turn.\nimport heapq\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\nN_TURNS = 100\nDRONES_PER_PLAYER = 30\nDRONE_CAPACITY = 5\nUPKEEP = 2.0\n\n\ndef build_map(n_nodes, edges):\n    adj = [[] for _ in range(n_nodes)]\n    for u, v in edges:\n        u, v = int(u), int(v)\n        if 0 <= u < n_nodes and 0 <= v < n_nodes and u != v:\n            adj[u].append(v)\n            adj[v].append(u)\n    adj = [sorted(set(row)) for row in adj]\n\n    distances = []\n    next_hop = [[-1] * n_nodes for _ in range(n_nodes)]\n    for start in range(n_nodes):\n        dist = [-1] * n_nodes\n        dist[start] = 0\n        q = deque([start])\n        while q:\n            u = q.popleft()\n            for v in adj[u]:\n                if dist[v] < 0:\n                    dist[v] = dist[u] + 1\n                    next_hop[start][v] = v if u == start else next_hop[start][u]\n                    q.append(v)\n        distances.append(dist)\n    return adj, distances, next_hop\n\n\ndef served(capacity_i, total_capacity, demand):\n    """The specification\'s per-player revenue payout at one node."""\n    if demand <= 0.0 or capacity_i <= 0.0:\n        return 0.0\n    denominator = max(total_capacity, demand)\n    return capacity_i * demand / denominator if denominator > 0.0 else 0.0\n\n\ndef node_margin(own_drones, opponent_drones, demand):\n    own_capacity = own_drones * DRONE_CAPACITY\n    opponent_capacity = opponent_drones * DRONE_CAPACITY\n    total_capacity = own_capacity + opponent_capacity\n    own_revenue = served(own_capacity, total_capacity, demand)\n    opponent_revenue = served(opponent_capacity, total_capacity, demand)\n    return own_revenue - opponent_revenue\n\n\ndef plan_targets(obs, distances, deadline):\n    n = int(obs.get("n_nodes", 0))\n    turn = max(0, min(N_TURNS - 1, int(obs.get("turn", 0))))\n    base = int(obs.get("player_base", 0))\n    own = list(obs.get("player_drones", [0] * n))\n    opponent = list(obs.get("opponent_drones", [0] * n))\n    forecast = obs.get("demand_forecast", [[] for _ in range(n)])\n    remaining = N_TURNS - turn\n\n    # Forecast entries are exact; beyond them, use the last observed value.\n    horizon = max((len(row) for row in forecast), default=0)\n    horizon = max(1, horizon)\n    demand_at = []\n    for node in range(n):\n        row = forecast[node] if node < len(forecast) else []\n        vals = [float(x) for x in row]\n        if not vals:\n            vals = [0.0]\n        demand_at.append(vals)\n\n    planned = [0] * n\n    allocated = 0\n    while allocated < DRONES_PER_PLAYER:\n        best_node = base\n        best_gain = 0.0\n        for node in range(n):\n            if node == base:\n                continue\n            travel = distances[base][node]\n            if travel < 0 or travel >= remaining:\n                continue\n            current_count = planned[node]\n            gain = 0.0\n            # Evaluate the unit from its arrival turn through the end of the game.\n            for offset in range(travel, remaining):\n                row = demand_at[node]\n                demand = row[offset] if offset < len(row) else row[-1]\n                before = node_margin(current_count, opponent[node], demand)\n                after = node_margin(current_count + 1, opponent[node], demand)\n                gain += after - before - UPKEEP\n            if gain > best_gain + 1e-9:\n                best_gain = gain\n                best_node = node\n        if best_gain <= 0.0 or time.perf_counter() >= deadline:\n            break\n        planned[best_node] += 1\n        allocated += 1\n\n    # Unallocated drones belong at the base, where they incur no upkeep.\n    planned[base] += DRONES_PER_PLAYER - allocated\n    return planned\n\n\ndef plan_to_action(own, target, distances, next_hop, adj):\n    n = len(own)\n    surplus = [max(0, int(own[i]) - int(target[i])) for i in range(n)]\n    deficit = [max(0, int(target[i]) - int(own[i])) for i in range(n)]\n    pairs = []\n    for source in range(n):\n        if surplus[source] <= 0:\n            continue\n        for dest in range(n):\n            if deficit[dest] > 0 and distances[source][dest] > 0:\n                pairs.append((distances[source][dest], source, dest))\n    pairs.sort()\n\n    moves = {}\n    for _, source, dest in pairs:\n        amount = min(surplus[source], deficit[dest])\n        if amount <= 0:\n            continue\n        step = next_hop[source][dest]\n        if step not in adj[source]:\n            continue\n        moves[(source, step)] = moves.get((source, step), 0) + amount\n        surplus[source] -= amount\n        deficit[dest] -= amount\n\n    # Validate each emitted move against start-of-turn counts and adjacency.\n    available = [int(x) for x in own]\n    action = []\n    for (source, dest), amount in sorted(moves.items()):\n        count = min(int(amount), available[source])\n        if count > 0 and dest in adj[source]:\n            action.append((int(source), int(dest), int(count)))\n            available[source] -= count\n    return action\n\n\nclass Strategy:\n    def __init__(self, player_id: int) -> None:\n        self.player_id = int(player_id)\n        self._map_key = None\n        self._adj = None\n        self._distances = None\n        self._next_hop = None\n        self._bad_reports = 0\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + max(0.001, 0.6 * float(TIME_BUDGET))\n        n = int(obs.get("n_nodes", 0))\n        edges = obs.get("edges", [])\n        key = (n, tuple(tuple(edge) for edge in edges))\n        if self._map_key != key:\n            self._adj, self._distances, self._next_hop = build_map(n, edges)\n            self._map_key = key\n\n        if (not bool(obs.get("action_format_correct_last_turn", True))\n                or int(obs.get("n_invalid_actions_last_turn", 0)) > 0):\n            self._bad_reports += 1\n        else:\n            self._bad_reports = 0\n\n        own = list(obs.get("player_drones", [0] * n))\n        if len(own) < n:\n            own.extend([0] * (n - len(own)))\n        target = plan_targets(obs, self._distances, deadline)\n\n        # After repeated legality feedback, use only direct, conservatively checked\n        # shortest-path steps; the same validated planner still guarantees legality.\n        action = plan_to_action(\n            own, target, self._distances, self._next_hop, self._adj\n        )\n        if not isinstance(action, list):\n            return []\n        return action\n'
_CORE_CLASS = 'Strategy'
_FALLBACK_SRC = None
_FALLBACK_CLASS = 'Strategy'
_ACT_LIMIT_S = 0.7
_CORE_SHARE = 0.75
_TIME_BUDGET = 0.25
_IMPORT_LIMIT_S = 4.5
_FALLBACK_IMPORT_LIMIT_S = 1.5
_CORE_INIT_LIMIT_S = 2.5
_FALLBACK_INIT_LIMIT_S = 1.5
_MAX_REPLY_CHARS = 900000

_MIN_FALLBACK_S = 0.05
_REPEAT_S = 0.05  # after the first alarm, re-fire every 50 ms until the call returns
_STATE = {"armed": False}
_GUARD_CODES = set()


class _GuardTimeout(BaseException):
    """Raised by the guard's timer. A BaseException: `except Exception` cannot swallow it."""


class _Sink:
    """Swallows output: strategy code must not flood the worker's stderr."""

    encoding = "utf-8"
    errors = "replace"

    def write(self, s):
        return len(s)

    def writelines(self, lines):
        return None

    def flush(self):
        return None

    def isatty(self):
        return False


_SINK = _Sink()


def _noop_print(*args, **kwargs):
    return None


def _on_alarm(signum, frame):
    if _STATE["armed"] and (frame is None or frame.f_code not in _GUARD_CODES):
        raise _GuardTimeout()


def _can_time():
    return (
        hasattr(_signal, "setitimer")
        and hasattr(_signal, "SIGALRM")
        and _threading.current_thread() is _threading.main_thread()
    )


def _plain(value):
    """(True, plain copy) if value is a literal within the reply limit, else (False, None)."""
    try:
        text = repr(value)
        if len(text) > _MAX_REPLY_CHARS:
            return False, None
        if not text.isascii() and len(text.encode("utf-8", "replace")) > _MAX_REPLY_CHARS:
            return False, None  # arena's reply limit counts bytes
        copy = _ast.literal_eval(text)
        if not bool(copy == value):  # NaN, or a type whose repr is not its value
            return False, None
        return True, copy
    except Exception:
        return False, None


def _call(fn, args, limit, check):
    """fn(*args) under a hard timer: (status, value, error, secs). Never raises.

    status: 'ok', 'timeout', 'exception' or 'bad' (check=True and not a plain literal).
    """
    status = "exception"
    value = None
    error = None
    timed = False
    prev_handler = None
    prev_timer = (0.0, 0.0)
    out, err, inp = _sys.stdout, _sys.stderr, _sys.stdin
    t0 = _time.perf_counter()
    try:
        if limit > 0 and _can_time():
            prev_handler = _signal.signal(_signal.SIGALRM, _on_alarm)
            prev_timer = _signal.setitimer(_signal.ITIMER_REAL, limit, _REPEAT_S)
            timed = True
        _sys.stdout = _sys.stderr = _SINK
        _sys.stdin = None  # arena's protocol pipe: untrusted code must not read it
        _STATE["armed"] = timed
        try:
            result = fn(*args)
            if check:
                ok, result = _plain(result)
                status = "ok" if ok else "bad"
            else:
                status = "ok"
            value = result
        except _GuardTimeout as e:
            status = "timeout"
            error = e
        except BaseException as e:
            status = "exception"
            error = e
    except BaseException as e:
        if status == "exception" and error is None:
            error = e
    finally:
        _STATE["armed"] = False
        if timed:
            try:
                _signal.setitimer(_signal.ITIMER_REAL, 0.0)
                _signal.signal(
                    _signal.SIGALRM, prev_handler if prev_handler is not None else _signal.SIG_DFL
                )
                if prev_timer[0] > 0:
                    spent = _time.perf_counter() - t0
                    _signal.setitimer(
                        _signal.ITIMER_REAL, max(prev_timer[0] - spent, 1e-4), prev_timer[1]
                    )
            except BaseException:
                pass
        _sys.stdout, _sys.stderr, _sys.stdin = out, err, inp
    if isinstance(error, _GuardTimeout):
        status = "timeout"
    return status, value, error, _time.perf_counter() - t0


_GUARD_CODES.add(_call.__code__)  # exempt already while the embedded sources load


def _act_of(strategy, obs):
    """strategy.act(obs): inside the timed call, so a missing or broken `act` is caught too."""
    return strategy.act(obs)


def _describe(status, error, secs, limit):
    if status == "timeout":
        where = ""
        try:
            if error is not None:
                frames = _traceback.extract_tb(error.__traceback__)
                frames = [f for f in frames if f.name not in ("_on_alarm", "_call")][-3:]
                where = "\ninterrupted at:\n" + "".join(_traceback.format_list(frames))
        except BaseException:
            where = ""
        return "timeout: no result within %.2f s (limit %.2f s)%s" % (secs, limit, where[-1500:])
    if status == "bad":
        return "bad output: not a plain Python literal within the reply limit"
    try:
        return "".join(_traceback.format_exception(error))[-4000:]
    except BaseException:
        return "exception (traceback unavailable)"


def _load(src, cls_name, label):
    n = 0
    while "_hz_%s_%d" % (label, n) in _sys.modules:
        n += 1
    name = "_hz_%s_%d" % (label, n)
    filename = "<%s>" % name
    _linecache.cache[filename] = (len(src), None, src.splitlines(True), filename)
    module = _types.ModuleType(name)
    module.__file__ = filename
    module.TIME_BUDGET = _TIME_BUDGET
    module.print = _noop_print
    _sys.modules[name] = module
    try:
        exec(compile(src, filename, "exec"), module.__dict__)
        module.TIME_BUDGET = _TIME_BUDGET
        module.print = _noop_print
        return getattr(module, cls_name)
    except BaseException:
        _sys.modules.pop(name, None)
        raise


_LOAD_ERRORS = {}


def _load_all():
    t0 = _time.perf_counter()
    loaded = {"core": None, "fallback": None}
    parts = (
        ("fallback", _FALLBACK_SRC, _FALLBACK_CLASS, _FALLBACK_IMPORT_LIMIT_S),
        ("core", _CORE_SRC, _CORE_CLASS, None),
    )
    for label, src, cls_name, limit in parts:
        if src is None:
            continue
        left = _IMPORT_LIMIT_S - (_time.perf_counter() - t0)
        limit = min(limit, left) if limit is not None else left
        limit = max(limit, 0.5)
        status, value, error, secs = _call(_load, (src, cls_name, label), limit, False)
        if status == "ok":
            loaded[label] = value
        else:
            _LOAD_ERRORS[label] = _describe(status, error, secs, limit)
    return loaded["core"], loaded["fallback"]


try:
    _CORE_CLS, _FALLBACK_CLS = _load_all()
except BaseException:
    _CORE_CLS, _FALLBACK_CLS = None, None


class _HzGuard:
    def __init__(self, player_id):
        self.player_id = player_id
        self._core = None
        self._fallback = None
        self._stats = {
            "turns": 0,
            "core_ok": 0,
            "core_exceptions": 0,
            "core_timeouts": 0,
            "core_bad_output": 0,
            "fallback_used": 0,
            "fallback_failures": 0,
            "none_used": 0,
            "max_core_s": 0.0,
            "first_core_traceback": _LOAD_ERRORS.get("core"),
            "core_loaded": _CORE_CLS is not None,
            "fallback_loaded": _FALLBACK_CLS is not None,
            "core_init_error": None,
            "fallback_init_error": None,
            "fallback_load_error": _LOAD_ERRORS.get("fallback"),
            "first_fallback_error": None,
        }
        try:
            if _CORE_CLS is not None:
                lim = _CORE_INIT_LIMIT_S
                status, value, error, secs = _call(_CORE_CLS, (player_id,), lim, False)
                if status == "ok":
                    self._core = value
                else:
                    msg = _describe(status, error, secs, lim)
                    self._stats["core_init_error"] = msg
                    if self._stats["first_core_traceback"] is None:
                        self._stats["first_core_traceback"] = msg
            if _FALLBACK_CLS is not None:
                lim = _FALLBACK_INIT_LIMIT_S
                status, value, error, secs = _call(_FALLBACK_CLS, (player_id,), lim, False)
                if status == "ok":
                    self._fallback = value
                else:
                    self._stats["fallback_init_error"] = _describe(status, error, secs, lim)
        except BaseException:
            pass

    def act(self, obs):
        try:
            return self._act(obs)
        except BaseException:
            return None

    def _act(self, obs):
        t0 = _time.perf_counter()
        st = self._stats
        st["turns"] += 1
        core, fallback = self._core, self._fallback
        saved = None
        if core is not None:
            if fallback is not None:
                try:
                    saved = repr(obs)  # the core may mutate obs; the fallback gets a fresh copy
                except Exception:
                    saved = None
            limit = _ACT_LIMIT_S * _CORE_SHARE
            status, value, error, secs = _call(_act_of, (core, obs), limit, True)
            if secs > st["max_core_s"]:
                st["max_core_s"] = secs
            if status == "ok":
                st["core_ok"] += 1
                return value
            if status == "timeout":
                st["core_timeouts"] += 1
            elif status == "bad":
                st["core_bad_output"] += 1
            else:
                st["core_exceptions"] += 1
            if st["first_core_traceback"] is None:
                st["first_core_traceback"] = _describe(status, error, secs, limit)
            error = None
        if fallback is not None:
            fobs = obs
            if saved is not None:
                try:
                    fobs = _ast.literal_eval(saved)
                except Exception:
                    fobs = obs
            left = _ACT_LIMIT_S - (_time.perf_counter() - t0)
            if left >= _MIN_FALLBACK_S:
                status, value, error, secs = _call(_act_of, (fallback, fobs), left, True)
                if status == "ok":
                    st["fallback_used"] += 1
                    return value
                st["fallback_failures"] += 1
                if st["first_fallback_error"] is None:
                    st["first_fallback_error"] = _describe(status, error, secs, left)
        st["none_used"] += 1
        return None

    def guard_stats(self):
        """Counters of this instance: how often the core answered, failed, fell back."""
        try:
            return dict(self._stats)
        except BaseException:
            return {}


for _fn in (_call, _HzGuard.__init__, _HzGuard.act, _HzGuard._act, _HzGuard.guard_stats):
    _GUARD_CODES.add(_fn.__code__)
del _fn


class Strategy(_HzGuard):
    """Guarded strategy: never raises, never exceeds its time limit."""
